{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C01"],
      "claim": "Direct mouse study of a closely related N-aryl piperazine amide showed ready BBB passage with high brain and spinal cord levels, supporting CNS access for the query's piperazine-amide core.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "In mice, a close piperazine-amide analogue had brain-to-serum AUC ratio >1 after both i.p. and p.o. dosing, demonstrating meaningful CNS exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "A pyridazine-containing analogue showed high brain uptake in an in vivo mouse distribution study, supporting the CNS permeability of the query's pyridazine motif.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "A direct rat measurement for a close isopropyl-aryl analogue gave a brain/plasma ratio of 1.66 ± 0.23 at 0.5 h after i.v. dosing, indicating good CNS penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "In rats, cymserine, an isopropyl-substituted analogue, entered brain with brain concentrations significantly above plasma (brain/plasma ratio ~40:1), demonstrating robust CNS uptake for isopropyl-aryl structures.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Ex vivo autoradiography in rats showed a close piperazine-amide H3 antagonist crossed the BBB with a brain-to-plasma ratio of ~1:1 and occupied central receptors.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Multiple high-transfer direct in vivo studies in rodents demonstrate that close structural analogues of the query—aryl piperazine amides, pyridazine-containing piperazines, and isopropyl-aryl compounds—cross the BBB with brain-to-plasma ratios ≥1, high brain uptake, or central receptor occupancy. The favorable passive-diffusion prior is consistent, and no contradictory experimental evidence was identified. Therefore the query is predicted to have meaningful CNS access.",
  "evidence_gaps": [
    "No direct experimental measurement for the exact query molecule; prediction relies on high-transfer analogues.",
    "No explicit P-gp/efflux assay for the query, though the neutral, low-basicity character and positive analogue data reduce concern.",
    "No human data for the exact query molecule."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "high",
      "card_ids": ["C01", "C02", "C05", "C06", "C08", "C11"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "aryl piperazine amides / pyridazine piperazines"
    }
  ],
  "revision_action": "initial"
}

